def topological_sort(graph):
    visited = set()
    order = []
    # 0 = unvisited, 1 = visiting (in current path), 2 = visited (fully processed)
    state = {}

    def visit(node):
        if node not in state:
            state[node] = 0
        if state[node] == 1:
            raise ValueError('cycle detected')
        if state[node] == 2:
            return
        state[node] = 1
        for dependency in graph.get(node, []):
            visit(dependency)
        state[node] = 2
        order.append(node)

    for node in graph:
        visit(node)
    return order
```

