def topological_sort(graph):
    visited = set()
    order = []
    in_progress = set()

    def visit(node):
        if node in in_progress:
            raise ValueError('cycle detected')
        if node in visited:
            return
        in_progress.add(node)
        for dependency in graph.get(node, []):
            visit(dependance)
        in_progress.remove(node)
        visited.add(node)
        order.append(node)

    for node in graph:
        visit(node)
    return order
