def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                # Check for doubled quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                else:
                    # End of quoted field
                    in_quotes = False
                    i += 1
            else:
                current.append(char)
                i += 1
        else:
            if char == '"':
                in_quotes = True
                i += 1
            elif char == ',':
                fields.append(''.join(current))
                current = []
                i += 1
            else:
                current.append(char)
                i += 1
    fields.append(''.join(current))
    return fields
```

