def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            i += 1  # skip opening quote
            field = ''
            while i < n:
                if line[i] == '"':
                    # Check for doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1  # skip closing quote
                        break
                else:
                    field += line[i]
                    i += 1
            fields.append(field)
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',' and line[i] != '\n' and line[i] != '\r':
                i += 1
            fields.append(line[start:i])
        if i < n and line[i] == ',':
            i += 1  # skip comma
        elif i < n and (line[i] == '\r' or line[i] == '\n'):
            i += 1
            if i < n and line[i] == '\n':
                i += 1
        else:
            break
    return fields
