from tokens import is_token_valid
from datetime import datetime

def is_token_expired(token, now):
    """
    Check if a token is expired.
    Tokens with expires_at <= now are considered expired.
    """
    if token.expires_at is None:
        return False
    return now >= token.expires_at

def is_token_revoked(token):
    """
    Check if a token is revoked.
    """
    return getattr(token, 'revoked', False)

def authorize(token, now):
    if is_token_expired(token, now):
        raise PermissionError('token expired')
    if is_token_revoked(token):
        raise PermissionError('token revoked')
    if not is_token_valid(token, now):
        raise PermissionError('token invalid or expired')
    return True
```

