    assert solution.find_rotation_point([5]) == 0


def test_empty_array():
    """Empty input must return -1."""
    assert solution.find_rotation_point([]) == -1


def test_all_same_elements():
    """Array with all identical elements should return 0."""
    assert solution.find_rotation_point([3, 3, 3]) == 0


def test_larger_rotated_array():
