def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, c in enumerate(s):
        if i < len(s) - 1 and vals[c] < vals[s[i + 1]]:
            total += vals[s[i + 1]] - vals[c]
            i += 1  # Skip the next character since it's been handled
            continue
        total += vals[c]
    return total
```

```python
def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, c in enumerate(s):
        current_val = vals[c]
        # If there is a next character and the current value is less than the next value,
        # subtract the current value (subtractive form)
        if i < len(s) - 1 and vals[s[i + 1]] > current_val:
            total -= current_val
        else:
            total += current_val
    return total
```

