from unittest.mock import patch, MagicMock

import stock


class TestStockCheck(unittest.TestCase):
    """Tests for stock.check() after fixing the bug in stock.py."""

    @patch('stock.available')
    def test_check_returns_zero_when_sku_count_equals_reserved(self, mock_available):
        """check(5, 5) should return 0 (available inventory)."""
        mock_available.return_value = 0
        result = stock.check(5, 5)
        self.assertEqual(result, 0)

    @patch('stock.available')
    def test_check_returns_positive_when_more_sku_than_reserved(self, mock_available):
        """check(10, 5) should return 5 (available inventory)."""
        mock_available.return_value = 5
        result = stock.check(10, 5)
        self.assertEqual(result, 5)

    @patch('stock.available')
    def test_check_returns_zero_when_reserved_exceeds_sku(self, mock_available):
        """check(5, 10) should return 0 (no available inventory)."""
        mock_available.return_value = 0
        result = stock.check(5, 10)
        self.assertEqual(result, 0)

    @patch('stock.available')
    def test_check_passes_correct_arguments_to_available(self, mock_available):
        """check should pass sku_count and reserved to available in correct order."""
        stock.check(7, 3)
        mock_available.assert_called_once_with(7, 3)

    @patch('stock.available')
    def test_check_handles_zero_sku_count(self, mock_available):
        """check(0, 0) should return 0."""
        mock_available.return_value = 0
        result = stock.check(0, 0)
        self.assertEqual(result, 0)

    @patch('stock.available')
    def test_check_handles_large_numbers(self, mock_available):
        """check with large numbers should work correctly."""
        mock_available.return_value = 1000
        result = stock.check(2000, 1000)
        self.assertEqual(result, 1000)

    @patch('stock.available')
    def test_check_does_not_modify_inputs(self, mock_available):
        """check should not modify the input arguments."""
        sku_count = 5
        reserved = 5
        mock_available.return_value = 0
        stock.check(sku_count, reserved)
        self.assertEqual(sku_count, 5)
        self.assertEqual(reserved, 5)


if __name__ == '__main__':
    unittest.main()

