def test_snap_to_grid_basic():
    """Test basic snapping: 1.3 with step 0.5 should snap to 1.0"""
    assert snap_to_grid(1.3, 0.5) == 1.0


def test_snap_to_grid_round_up():
    """Test snapping that rounds up: 1.6 with step 0.5 should snap to 2.0"""
    assert snap_to_grid(1.6, 0.5) == 2.0


def test_snap_to_grid_exact():
    """Test when value is already on grid: 1.5 with step 0.5 should stay 1.5"""
    assert snap_to_grid(1.5, 0.5) == 1.5


def test_snap_to_grid_negative():
    """Test negative values: -1.3 with step 0.5 should snap to -1.0"""
    assert snap_to_grid(-1.3, 0.5) == -1.0


def test_snap_to_grid_zero_step():
    """Test with step=0: any value should snap to 0"""
    assert snap_to_grid(1.5, 0.0) == 0.0


def test_snap_to_grid_large_step():
    """Test with large step: 10.7 with step 5.0 should snap to 10.0"""
    assert snap_to_grid(10.7, 5.0) == 10.0


def test_snap_to_grid_small_values():
    """Test with small floating point values: 0.25 with step 0.1 should snap to 0.2"""
    assert snap_to_grid(0.25, 0.1) == 0.2


def test_snap_to_grid_very_small_step():
    """Test with very small step: 0.05 with step 0.01 should snap to 0.05"""
    assert snap_to_grid(0.05, 0.01) == 0.05

